const item = $input.first();
const aiOutput = item?.json?.output || '';

console.log('AI Output preview:', aiOutput.substring(0, 300));

// ── TAG: [USER_STATUS] ──────────────────────────────────────
let userStatus = '';
const statusMatch = aiOutput.match(/\[USER_STATUS:(PARENT|STUDENT)\]/);
if (statusMatch && statusMatch[1]) {
  userStatus = statusMatch[1];
  console.log('👤 USER_STATUS detected:', userStatus);
}

// ── FALLBACK: Detect from conversation if tag missing ────────
if (!userStatus && item.json.is_new_user) {
  const userMessage = item.json.original_message?.toLowerCase() || '';
  const aiResponse = aiOutput.toLowerCase();

  // Check if this looks like a status response conversation
  const isStatusConversation = 
    aiResponse.includes('terima kasih sudah memberi tahu') ||
    aiResponse.includes('baik om/tante') ||
    aiResponse.includes('baik! terima kasih') ||
    (aiResponse.includes('om/tante') && userMessage.length < 50) ||
    (aiResponse.includes('kamu') && userMessage.length < 50);

  if (isStatusConversation) {
    // Detect PARENT keywords in user message
    if (userMessage.includes('orang tua') || 
        userMessage.includes('ortu') || 
        userMessage.includes('ayah') || 
        userMessage.includes('ibu') ||
        userMessage.includes('bapak') ||
        userMessage.includes('mama') ||
        userMessage.includes('papa') ||
        userMessage.includes('anak saya') ||
        userMessage.includes('anak kami')) {
      userStatus = 'PARENT';
      console.log('⚠️ FALLBACK: Detected PARENT from user message');
    }
    // Detect STUDENT keywords in user message
    else if (userMessage.includes('murid') || 
             userMessage.includes('saya sendiri') ||
             userMessage.includes('saya yang') ||
             userMessage.includes('calon muridnya') ||
             (userMessage.includes('saya') && !userMessage.includes('anak'))) {
      userStatus = 'STUDENT';
      console.log('⚠️ FALLBACK: Detected STUDENT from user message');
    }
  }
}

// ── TAG: [SEND_GFORM] ──────────────────────────────────────────
let isSendGForm = aiOutput.includes('[SEND_GFORM]');

// ── FALLBACK: Detect if AI forgot to add tag ──────────────────
if (!isSendGForm) {
  const outputLower = aiOutput.toLowerCase();

  // 1. Cek kehadiran URL forms.gle — paling reliable, kalau ada pasti GForm dikirim
  const hasFormsUrl = aiOutput.includes('forms.gle');

  // 2. Cek phrase patterns (expanded dari sebelumnya)
  const forgotTagPatterns = [
    // patterns lama
    'link pendaftaran sudah saya kirim',
    'link pendaftaran mock interview sudah saya kirim',
    'silakan isi formnya',
    'form sudah saya kirim',
    // patterns baru — catch output AI yang actual
    'link pendaftarannya',       // "ini link pendaftarannya yaa"
    'link pendaftaran',          // variasi umum
    'ini linknya',               // "ini linknya yaa"
    'silakan diisi',             // "silakan diisi yaa" (bukan "isi formnya")
    'link pendaftaran mock',     // mock interview variant
    'ini link mock',
  ];

  const mentionedSendingForm = forgotTagPatterns.some(pattern =>
    outputLower.includes(pattern)
  );

  if (hasFormsUrl || mentionedSendingForm) {
    isSendGForm = true;
    const reason = hasFormsUrl ? 'forms.gle URL detected' : 'phrase pattern matched';
    console.log(`⚠️ FALLBACK: AI forgot [SEND_GFORM] tag - auto-correcting (${reason})`);
  }
}

// ── TAG: [TALK_TO_SAM] ─────────────────────────────────────────
let isTalkToSam = aiOutput.includes('[TALK_TO_SAM]');

// ── FALLBACK: Detect if AI forgot tag ─────────────────────────
if (!isTalkToSam) {
  const outputLower = aiOutput.toLowerCase();
  const talkToSamPatterns = [
    'sampaikan ke sam',
    'saya sampaikan ke sam',
    'dibalas langsung sama dia',
    'dibales langsung sama dia',
    'kalau dia sudah ada waktu',
  ];
  if (talkToSamPatterns.some(p => outputLower.includes(p))) {
    isTalkToSam = true;
    console.log('⚠️ FALLBACK: AI forgot [TALK_TO_SAM] tag - auto-correcting');
  }
}

// ── TAG: [MOCK_INTERVIEW_BOOKING] ─────────────────────────────
let isMockBooking = false;
let mockBookingData = {};
const mockMatch = aiOutput.match(/\[MOCK_INTERVIEW_BOOKING\](.*?)\[\/MOCK_INTERVIEW_BOOKING\]/s);
if (mockMatch && mockMatch[1]) {
  isMockBooking = true;
  const c = mockMatch[1];
  const namaM    = c.match(/Nama:([^|]+)/);
  const sesiM    = c.match(/Sesi:([^|]+)/);
  const noWaM    = c.match(/NoWA:([^|\\]]+)/);
  mockBookingData = {
    nama:  namaM ? namaM[1].trim() : '',
    sesi:  sesiM ? sesiM[1].trim() : '',
    noWA:  noWaM ? noWaM[1].trim() : '',
  };
}

// ── TAG: [UNKNOWN] ────────────────────────────────────────────
const isUnknown = aiOutput.includes('[UNKNOWN]');

// ── TAG: [PENDAFTARAN] (backward compat) ──────────────────────
let isPendaftaran = false;
let pendaftaranData = {};
const pendMatch = aiOutput.match(/\[PENDAFTARAN\](.*?)\[\/PENDAFTARAN\]/s);
if (pendMatch && pendMatch[1]) {
  isPendaftaran = true;
  const c = pendMatch[1];
  const namaM    = c.match(/Nama:([^|]+)/);
  const programM = c.match(/Program:([^|]+)/);
  const batchM   = c.match(/Batch:([^|]+)/);
  const asalM    = c.match(/Asal:([^|\\]]+)/);
  pendaftaranData = {
    nama:    namaM    ? namaM[1].trim()    : '',
    program: programM ? programM[1].trim() : '',
    batch:   batchM   ? batchM[1].trim()   : '',
    asal:    asalM    ? asalM[1].trim()    : '',
  };
}

// ── DATA_COMPLETE ──────────────────────────────────────────────
let isDataComplete = false;
let dataComplete = {};
const dcMatch = aiOutput.match(/\[DATA_COMPLETE\](.*?)\[\/DATA_COMPLETE\]/s);
if (dcMatch && dcMatch[1]) {
  isDataComplete = true;
  const c = dcMatch[1];
  const namaM    = c.match(/Nama:([^|]+)/);
  const noWaM    = c.match(/NoWA:([^|]+)/);
  const programM = c.match(/Program:([^|\\]]+)/);
  dataComplete = {
    nama:    namaM    ? namaM[1].trim() : '',
    noWA:    noWaM    ? noWaM[1].trim() : '',
    program: programM ? programM[1].trim() : '',
  };
}

// ── CLEAN OUTPUT (remove all tags before sending to user) ──────
let cleanOutput = aiOutput
  .replace(/\[SEND_GFORM\]/g, '')
  .replace(/\[MOCK_INTERVIEW_BOOKING\].*?\[\/MOCK_INTERVIEW_BOOKING\]/gs, '')
  .replace(/\[PENDAFTARAN\].*?\[\/PENDAFTARAN\]/gs, '')
  .replace(/\[DATA_COMPLETE\].*?\[\/DATA_COMPLETE\]/gs, '')
  .replace(/\[UNKNOWN\]/g, '')
  .replace(/\[USER_STATUS:(PARENT|STUDENT)\]/g, '')
  .replace(/\[TALK_TO_SAM\]/g, '')
  .trim();

// ── CLEAN MARKDOWN FORMATTING (URL-safe) ──────────────────────
// Step 1: Mask semua URL dengan placeholder supaya tidak kena regex markdown
const urlRegex = /https?:\/\/[^\s)]+/g;
const maskedUrls = [];
cleanOutput = cleanOutput.replace(urlRegex, (match) => {
  maskedUrls.push(match);
  return `\x00URL${maskedUrls.length - 1}\x00`;
});

// Step 2: Strip markdown (URL sudah aman di balik placeholder)
cleanOutput = cleanOutput
  .replace(/\*\*([^*]+)\*\*/g, '$1')  // **text** -> text
  .replace(/\*([^*]+)\*/g, '$1')      // *text* -> text
  .replace(/_([^_]+)_/g, '$1')        // _text_ -> text
  .replace(/~~([^~]+)~~/g, '$1')      // ~~text~~ -> text
  .replace(/`([^`]+)`/g, '$1')        // `code` -> text
  .replace(/[\*_~`]/g, '');           // sweep sisa karakter

// ── SAFETY NET: sanitasi tanda baca terlarang (deterministik) ──
cleanOutput = cleanOutput
  .replace(/(\d)\s*[—–]\s*(\d)/g, '$1-$2')  // "3–5" -> "3-5" (range angka, BUKAN koma)
  .replace(/\s*[—–]\s*/g, ', ')             // em/en-dash pemisah -> koma
  .replace(/\s*;\s*/g, ', ')                // titik-koma -> koma
  .replace(/\s{2,}/g, ' ')
  .replace(/\s+([,.])/g, '$1')
  .replace(/,\s*,/g, ',')
  .trim();

// Step 3: Restore URL yang asli
cleanOutput = cleanOutput.replace(
  /\x00URL(\d+)\x00/g,
  (_, idx) => maskedUrls[parseInt(idx)]
);

// ── SAFETY NET: hapus sapaan honorifik apapun (deterministik) ──
// VIRA tidak pernah menyapa user dengan honorifik. Jaring pengaman
// kalau model lolos (Bapak/Ibu, Om/Tante, Pak/Bu, dll).
cleanOutput = cleanOutput
  .replace(/(^|\n)\s*(Om\s*\/?\s*Tante|Bapak\s*\/?\s*Ibu|Pak\s*\/?\s*Bu|Ayah\s*\/?\s*Bunda)\s*,\s*/gi, '$1')
  .replace(/\s*\b(Om\s*\/?\s*Tante|Bapak\s*\/?\s*Ibu|Pak\s*\/?\s*Bu|Ayah\s*\/?\s*Bunda)\b\s*/gi, ' ')
  .replace(/\s{2,}/g, ' ')
  .replace(/\s+,/g, ',')
  .replace(/,\s*,/g, ',')
  .replace(/(^|\n)\s*,\s*/g, '$1')
  .trim();
cleanOutput = cleanOutput.replace(/(^|\n)([a-z])/g, (m, p1, p2) => p1 + p2.toUpperCase());

if (isSendGForm)   console.log('📋 SEND_GFORM tag detected');
if (isMockBooking) console.log('📅 MOCK_INTERVIEW_BOOKING detected:', JSON.stringify(mockBookingData));
if (isUnknown)     console.log('❓ UNKNOWN tag detected');
if (userStatus)    console.log('👤 USER_STATUS detected:', userStatus);

// ── RETURN WITH ALL REQUIRED FIELDS ──────
return [{
  json: {
    ...item.json,
    cleanOutput,
    isSendGForm,
    isMockBooking,
    mockBookingData,
    isUnknown,
    isPendaftaran,
    pendaftaranData,
    isDataComplete,
    dataComplete,
    userStatus,
    isTalkToSam,
    should_ask_status: $('Cek_user_status').first().json.should_ask_status,
    nama:    pendaftaranData.nama    || dataComplete.nama    || mockBookingData.nama || '',
    program: pendaftaranData.program || dataComplete.program || 'Mock Interview',

    // ── FIELDS FOR IF NODES (CRITICAL!) ──────
    needs_unknown: isUnknown ? 'true' : 'false',
    needs_status_update: userStatus !== '',
    can_record_to_sheet: isMockBooking || isPendaftaran || isDataComplete,
  }
}];

const webhookData = $input.first();
const body = webhookData.json.body || {};

// Ambil data dari Kirimi
const userMessage = body.message || "";
const messageType = body.messageType || "";
const userNumber = body.from || "unknown";  // ← TIDAK strip @lid, passthrough as-is
const userName = body.name || body.pushName || body.notifyName || "User";
const isFromMe = body.isFromMe === true;
const eventType = body.event || "";

// Filter: hanya pesan teks yang tidak kosong
if (messageType !== "text" || !userMessage || userMessage.trim() === "") {
    console.log('⛔ STOP: Bukan pesan teks valid');
    return [];
}

console.log('✅ LANJUT: Pesan teks valid dari user');
console.log('📱 No WA:', userNumber);

// Counter sederhana
let counter = $vars.chatCounter || 0;
counter++;
$vars.chatCounter = counter;

// Format tanggal & jam WIB
const now = new Date();
const formattedDate = now.toLocaleDateString('en-GB', {
    timeZone: 'Asia/Jakarta',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric'
});
const formattedTime = now.toLocaleTimeString('id-ID', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    hour12: false,
    timeZone: 'Asia/Jakarta'
}).replace(/\./g, ':');

const processStartTs = Date.now();

const aiInputText = `[SYSTEM_DATA]
CHAT_COUNTER: ${counter}
USER_NAME: ${userName}
USER_MESSAGE: "${userMessage}"

[USER QUERY]
${userMessage}`;

return [{
    json: {
        chat_counter: counter,
        user_wa: userNumber,
        user_name: userName,
        formatted_date: formattedDate,
        formatted_time: formattedTime,
        ai_input_text: aiInputText,
        original_message: userMessage,
        body: body,
        message_type: messageType,
        process_start_ts: processStartTs
    }
}];

// ====================================================================
// FINAL FIX: Handle empty strings dengan || operator
// ====================================================================

const debugLog = [];

try {
    const allItems = $input.all();
    debugLog.push("Step 1: Received " + allItems.length + " items from Read STATS");

    // ====================================================================
    // Ambil data dari Chat Counter
    // ====================================================================
    const chatCounterNode = $('Chat Counter').first();
    if (!chatCounterNode) {
        throw new Error("Chat Counter node not found!");
    }

    const chatCounter = chatCounterNode.json;
    if (!chatCounter) {
        throw new Error("Chat Counter json is empty!");
    }

    const searchNoWA = chatCounter.user_wa;
    const userName = chatCounter.user_name || "User";
    const userMessage = chatCounter.original_message || "";

    debugLog.push("Step 2: Chat Counter data OK");
    debugLog.push("  - No WA: " + searchNoWA);
    debugLog.push("  - Nama: " + userName);
    debugLog.push("  - Pesan: " + userMessage);

    if (!searchNoWA) {
        throw new Error("user_wa is missing!");
    }

    // ====================================================================
    // Process sheet rows
    // ====================================================================
    const sheetRows = allItems
        .filter(item => {
            const data = item?.json || item;
            if (!data || Object.keys(data).length === 0) {
                return false;
            }
            return !!(data['No WA'] || data.no_wa || data.NoWA || data['no wa']);
        })
        .map(item => item?.json || item);

    debugLog.push("Step 3: Sheet rows found: " + sheetRows.length);

    // ====================================================================
    // Find existing row
    // ====================================================================
    const searchNoWAStr = searchNoWA.toString();
    const existingRow = sheetRows.find(row => {
        const rowNoWA = row['No WA'] ?? row.no_wa ?? row.NoWA ?? row['no wa'];
        return rowNoWA && rowNoWA.toString() === searchNoWAStr;
    });

    const isNewUser = !existingRow;
    debugLog.push("Step 4: User status = " + (isNewUser ? "NEW USER" : "EXISTING USER"));

    // ====================================================================
    // Calculate values - FIXED: Pakai || untuk handle empty strings
    // ====================================================================
    let counter, pesanPertama, tanggalPertama, intensitasChat;

    if (existingRow) {
        // User sudah ada
        debugLog.push("Step 5a: Existing user - raw values:");
        debugLog.push("  - existingRow.Counter = '" + existingRow.Counter + "' (type: " + typeof existingRow.Counter + ")");
        debugLog.push("  - existingRow['Pesan Pertama'] = '" + existingRow['Pesan Pertama'] + "' (type: " + typeof existingRow['Pesan Pertama'] + ")");

        // FIX: Pakai || untuk handle empty string, bukan ??
        counter = parseInt(existingRow.Counter || existingRow.counter || 0) + 1;
        intensitasChat = parseInt(existingRow['Intensitas Chat'] || existingRow.intensitas_chat || 0) + 1;

        // FIX: Pakai || dan trim check untuk handle empty string
        const pesanLama = existingRow['Pesan Pertama'] || existingRow.pesan_pertama;
        pesanPertama = (pesanLama && pesanLama.trim() !== '') ? pesanLama : userMessage;

        tanggalPertama = existingRow.Tanggal || existingRow.tanggal || null;

        debugLog.push("Step 5b: Existing user processed");
        debugLog.push("  - Counter: " + counter);
        debugLog.push("  - Intensitas: " + intensitasChat);
        debugLog.push("  - Pesan Pertama: '" + pesanPertama + "'");
    } else {
        // User baru
        counter = 1;
        intensitasChat = 1;
        pesanPertama = userMessage;
        tanggalPertama = null;

        debugLog.push("Step 5: New user processed");
        debugLog.push("  - Counter: " + counter);
        debugLog.push("  - Intensitas: " + intensitasChat);
        debugLog.push("  - Pesan Pertama: '" + pesanPertama + "'");
    }

    // Verify
    debugLog.push("Step 6: Pre-return verification:");
    debugLog.push("  - counter value: " + counter + " (type: " + typeof counter + ")");
    debugLog.push("  - pesanPertama value: '" + pesanPertama + "' (length: " + pesanPertama.length + ")");

    // ====================================================================
    // Set tanggal
    // ====================================================================
    if (!tanggalPertama) {
        const now = new Date();
        tanggalPertama = now.toLocaleDateString('en-GB', {
            timeZone: 'Asia/Jakarta',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        });
    }

    const jamWIB = new Date().toLocaleTimeString('id-ID', {
        hour: '2-digit',
        minute: '2-digit',
        hour12: false,
        timeZone: 'Asia/Jakarta'
    }).replace('.', ':');

    // ====================================================================
    // Build output
    // ====================================================================
    const outputData = {
        "No WA": searchNoWA,
        "Tanggal": tanggalPertama,
        "TanggalSekarang": new Date().toLocaleDateString('en-GB', {  // ← TAMBAH INI
            timeZone: 'Asia/Jakarta',
            day: '2-digit',
            month: '2-digit',
            year: 'numeric'
        }),
        "Jam": jamWIB,
        "Nama": userName,
        "Pesan Pertama": pesanPertama,
        "Counter": counter,
        "Intensitas Chat": intensitasChat,
        "Last Timestamp": chatCounter.webhook_timestamp || Math.floor(Date.now()/1000),

        // DEBUG INFO - bisa hapus nanti kalau udah oke
        "_DEBUG": {
            "logs": debugLog,
            "isNewUser": isNewUser,
            "sheetRowsCount": sheetRows.length
        }
    };

    return [{
        json: outputData
    }];

} catch (error) {
    debugLog.push("ERROR: " + error.message);

    return [{
        json: {
            "No WA": "ERROR",
            "Counter": null,
            "Pesan Pertama": "",
            "Intensitas Chat": null,
            "_DEBUG": {
                "error": error.message,
                "logs": debugLog
            }
        }
    }];
}

const chatCounter = $('Chat Counter').first().json;

// DATA LANGSUNG DARI CHAT COUNTER NODE
const userNumber = chatCounter.user_wa;
const userName = chatCounter.user_name;
const userMessage = chatCounter.original_message;   // ← perbaikan utama

// VALIDASI SEDERHANA
if (!userNumber) {
  throw new Error("user_wa tidak ditemukan di input!");
}

console.log("✅ Data berhasil di-extract:");
console.log("- No WA:", userNumber);
console.log("- Nama:", userName);
console.log("- Pesan:", userMessage);

return [{
  json: {
    search_no_wa: userNumber,
    user_name: userName,
    user_message: userMessage,
    timestamp: chatCounter.formatted_date + ' ' + chatCounter.formatted_time + ' WIB',
    source: "chat_counter_node",
    is_valid: userNumber !== "unknown"
  }
}];

// Cek apakah Kirimi API sukses
const input = $input.first();
const responseData = input.json;

// Kirimi API return success jika ada field 'status' = true atau 'data'
const isSuccess = responseData.status === true || 
                  responseData.success === true ||
                  (responseData.data && responseData.data.id) ||
                  (responseData.message && responseData.message !== 'error');

if (!isSuccess) {
  console.log('❌ Kirimi API Response Error:', JSON.stringify(responseData));
  throw new Error('Kirimi API gagal: ' + JSON.stringify(responseData));
}

console.log('✅ Kirimi API sukses:', JSON.stringify(responseData));
return [input];

// Rate Limiter: cegah spam (maks 5 pesan per menit per user)
const input = $input.first().json;
const userWa = input.user_wa;
const now = Date.now();

// Global store menggunakan $workflow static data
const staticData = $getWorkflowStaticData('global');
const rateLimits = staticData.rateLimits || {};

const userKey = `rl_${userWa}`;
const windowMs = 60000; // 1 menit
const maxMessages = 5;

if (!rateLimits[userKey]) {
  rateLimits[userKey] = { count: 1, windowStart: now };
} else {
  const elapsed = now - rateLimits[userKey].windowStart;
  if (elapsed > windowMs) {
    // Reset window baru
    rateLimits[userKey] = { count: 1, windowStart: now };
  } else {
    rateLimits[userKey].count++;
  }
}

staticData.rateLimits = rateLimits;

const isRateLimited = rateLimits[userKey].count > maxMessages;

if (isRateLimited) {
  console.log(`⛔ RATE LIMITED: ${userWa} sudah ${rateLimits[userKey].count} pesan dalam 1 menit`);
  return [];
}

console.log(`✅ RATE OK: ${userWa} pesan ke-${rateLimits[userKey].count}`);
return [$input.first()];

// ============================================================
// HUMAN-IN-THE-LOOP CHECK
// Baca kolom 'bot_mode' dari STATS sheet untuk user ini.
// Jika bot_mode = 'OFF' → Sam sedang handle manual → stop, jangan reply.
// Jika kosong / 'ON' / apapun selain 'OFF' → bot aktif, lanjut.
// ============================================================

const input = $input.first().json;
const userWa = input.user_wa;

// Ambil data STATS dari node Read STATS (dijalankan sebelum node ini)
// Node Read STATS membaca seluruh sheet, kita filter by No WA
const statsRows = $('Read STATS for HITL').all();
const userRow = statsRows.find(r => {
  const wa = String(r.json['No WA'] || '').trim();
  return wa === String(userWa).trim();
});

const botMode = userRow ? String(userRow.json['bot_mode'] || '').trim().toUpperCase() : '';

if (botMode === 'OFF') {
  console.log(`👨‍💼 HITL AKTIF untuk ${userWa} — Sam sedang handle manual, bot berhenti.`);
  return [];
}

console.log(`🤖 Bot mode AKTIF untuk ${userWa} (bot_mode="${botMode}") — lanjut ke AI.`);
return [$input.first()];

